<section class="garden-panel" id="project-documents"><div class="garden-panel-heading"><div><span class="garden-kicker">ONE PROJECT. CONNECTED RECORDS.</span><h2>Documents & costs</h2></div></div><div class="garden-document-actions">
<?php if ($editable && $ci->permissions('quotation_add') && in_array($project->stage,['enquiry','inspection','quoted'],true)): ?><a class="garden-button" href="<?= base_url('quotation/add?garden_project_id='.$jobId); ?>">+ Create linked quotation</a><?php endif; ?>
<?php if ($editable && $ci->permissions('sales_add') && $project->quotation_id && !$project->sales_id && in_array($project->stage,['approved','deposit','execution','completed','paid'],true)): ?><a class="garden-button" href="<?= base_url('sales/quotation/'.(int)$project->quotation_id.'?garden_project_id='.$jobId); ?>">+ Create invoice from quotation</a><?php endif; ?>
<?php if ($editable && $ci->permissions('expense_add')): ?><a class="garden-button" href="<?= base_url('expense/add?garden_project_id='.$jobId); ?>">+ Record linked expense</a><?php endif; ?></div>
<div class="garden-document-cards">
<?php if ($project->quotation_id && $ci->permissions('quotation_view')): $linkedQuote=null;foreach($garden_quotes as $q) if((int)$q->id===(int)$project->quotation_id)$linkedQuote=$q; ?><a class="garden-document-card" href="<?= base_url('quotation/invoice/'.(int)$project->quotation_id); ?>"><i class="fa fa-file-text-o" aria-hidden="true"></i><small>Quotation · Revision <?= (int)$project->quotation_revision; ?></small><strong><?= htmlspecialchars($linkedQuote ? ($linkedQuote->quotation_code ?: '#'.$linkedQuote->id) : '#'.$project->quotation_id); ?></strong><span><?= htmlspecialchars($linkedQuote->lifecycle_status ?? 'Linked'); ?></span></a><?php endif; ?>
<?php if ($project->sales_id && $ci->permissions('sales_view')): ?><a class="garden-document-card" href="<?= base_url('sales/invoice/'.(int)$project->sales_id); ?>"><i class="fa fa-file-o" aria-hidden="true"></i><small>Customer invoice</small><strong><?php $linkedInvoice=null;foreach($garden_invoices as $i)if((int)$i->id===(int)$project->sales_id)$linkedInvoice=$i; ?><?= htmlspecialchars($linkedInvoice ? ($linkedInvoice->sales_code ?: '#'.$linkedInvoice->id) : '#'.$project->sales_id); ?></strong><span>Open invoice & payments ↗</span></a><?php endif; ?></div>
<?php if ($garden_finance): ?><div class="garden-project-money"><?php foreach (['actual_material_cost'=>'Recorded material cost','linked_expenses'=>'Linked expenses','cash_collected'=>'Cash collected','outstanding'=>'Invoice balance'] as $key=>$label): ?><div><small><?= $label; ?></small><strong><?= $garden_finance[$key]===null ? 'No invoice yet' : store_number_format($garden_finance[$key]); ?></strong></div><?php endforeach; ?></div><p class="garden-kpi-note">Cash received is separate from invoice value. Recorded costs are not final project profit until all costs, returns and taxes are reconciled.</p><?php endif; ?>
<?php if ($ci->permissions('expense_view')): ?><h3 class="garden-document-heading">Linked expenses <span><?= count($garden_linked_expenses); ?></span></h3><div class="garden-document-cards"><?php foreach ($garden_linked_expenses as $expense): ?><article class="garden-document-card"><i class="fa fa-credit-card" aria-hidden="true"></i><small><?= htmlspecialchars(($expense->expense_code ?: '#'.$expense->id).' · '.$expense->expense_date); ?></small><strong><?= store_number_format($expense->expense_amt); ?></strong><p><?= htmlspecialchars($expense->expense_for); ?></p><span><?= (int)$expense->status===1 ? 'Included in recorded expenses' : 'Inactive · excluded from total'; ?></span><?php if ($ci->permissions('expense_edit')): ?><a href="<?= base_url('expense/update/'.(int)$expense->id); ?>">Open expense ↗</a><?php endif; ?></article><?php endforeach; ?></div>
<?php if (!$garden_linked_expenses): ?><p class="garden-muted">No expenses linked yet. Add labour, transport and other project costs as separate records.</p><?php endif; ?>
<?php if ($editable): ?><details class="garden-record-compose"><summary class="garden-create-summary"><span>Link an existing expense</span></summary><form method="post" action="<?= base_url('garden/project_expense'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><label>Expense<select name="expense_id" data-garden-select hidden required><option value="">Choose expense</option><?php foreach ($garden_expenses as $expense): ?><option value="<?= (int)$expense->id; ?>"><?= htmlspecialchars(($expense->expense_code ?: '#'.$expense->id).' · '.$expense->expense_for.' · '.store_number_format($expense->expense_amt)); ?></option><?php endforeach; ?></select></label><button class="garden-button">Link expense card</button></form></details><?php endif; ?><?php endif; ?>
<?php if ($editable && $project->stage==='execution' && $ci->permissions('items_view')): ?><details class="garden-record-compose"><summary class="garden-create-summary"><span>Record additional materials used</span></summary><form method="post" action="<?= base_url('garden/project_material'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>"><p class="garden-muted">Products already issued on the invoice cannot be deducted again. Uses your default branch.</p><label>Material<select name="item_id" data-garden-select hidden><option value="">Choose material</option><?php foreach ($garden_items as $item):if((int)$item->service_bit===1 || !empty($item->is_bundle))continue; ?><option value="<?= (int)$item->id; ?>"><?= htmlspecialchars($item->item_name); ?></option><?php endforeach; ?></select></label><label>Quantity<input type="number" min="0.01" step="0.01" name="qty" required></label><button class="garden-button">Record material issue</button></form></details><?php endif; ?>
</section>
